rustc_index :: newtype_index ! { #[doc = " Represents a subscope of `block` for a binding that is introduced"] #[doc = " by `block.stmts[first_statement_index]`. Such subscopes represent"] #[doc = " a suffix of the block. Note that each subscope does not include"] #[doc = " the initializer expression, if any, for the statement indexed by"] #[doc = " `first_statement_index`."] #[doc = ""] #[doc = " For example, given `{ let (a, b) = EXPR_1; let c = EXPR_2; ... }`:"] #[doc = ""] #[doc = " * The subscope with `first_statement_index == 0` is scope of both"] #[doc = "   `a` and `b`; it does not include EXPR_1, but does include"] #[doc = "   everything after that first `let`. (If you want a scope that"] #[doc = "   includes EXPR_1 as well, then do not use `Scope::Remainder`,"] #[doc = "   but instead another `Scope` that encompasses the whole block,"] #[doc = "   e.g., `Scope::Node`."] #[doc = ""] #[doc = " * The subscope with `first_statement_index == 1` is scope of `c`,"] #[doc = "   and thus does not include EXPR_2, but covers the `...`."] #[derive (HashStable)] #[encodable] #[orderable] pub struct FirstStatementIndex {}
}